export default function Attendance() {
  const startAttendance = () => {
    fetch("http://localhost:5000/start-face-attendance")
      .then(res => res.text())
      .then(msg => alert(msg))
      .catch(() => alert("Camera not detected"));
  };

  return (
    <div className="card">
      <h2>Face Based Attendance</h2>
      <button onClick={startAttendance}>
        Start Face Attendance
      </button>
    </div>
  );
}
